"""Render result sections in the README and report directly from saved tables."""
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]

def f(v, digits=6):
    try: return f"{float(v):.{digits}g}"
    except (TypeError,ValueError): return str(v)
def md_table(df, columns, headers=None, digits=6):
    headers=headers or columns
    lines=['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']
    for _,r in df.iterrows():
        lines.append('| '+' | '.join(f(r[c],digits) for c in columns)+' |')
    return '\n'.join(lines)
def main():
    tables=ROOT/'results/tables'
    ideal=pd.read_csv(tables/'ideal_architecture_results.csv')
    starts=ideal[ideal.architecture=='ideal logical'].sort_values(['g','seed'])
    comp=pd.read_csv(tables/'AB_comparison.csv')
    pooled=comp[comp.row_type=='summary_by_g_arch'].sort_values(['g','architecture'])
    paired=comp[(comp.row_type=='paired_difference') & (comp.g.astype(str)=='all')]
    exact=pd.read_csv(tables/'exact_crosscheck.csv').sort_values('g')
    decomp=pd.read_csv(tables/'noisy_error_decomposition.csv')
    gdesc=pd.read_csv(tables/'graph_descriptors.csv')
    table_starts=md_table(starts,['g','seed','objective_or_accuracy','classical_reference','approximation_or_error','optimizer_success','optimizer_termination_message'],['g','init seed','VQE energy','exact energy','Absolute error','optimizer success','termination'])
    table_pooled=md_table(pooled,['g','architecture','n_runs','optimizer_converged_starts','optimizer_failed_starts','noisy_energy_mean','total_noisy_absolute_error_mean','relative_absolute_error_mean','shot_sem_mean'],['g','architecture','n','converged','failed','mean sampled E','mean abs total error','mean relative abs error','mean shot SEM'])
    table_paired=md_table(paired,['n_pairs','mean','sample_sd','sem'],['matched pairs','mean A−B','sample SD','SEM'])
    table_exact=md_table(exact,['g','dense_ground_energy','max_abs_spectrum_diff_dense_free_fermion','magnetization_x_sum_dense'],['g','exact E₀','max spectrum diff','Σ⟨Xᵢ⟩'])
    table_dec=md_table(decomp.groupby('architecture',as_index=False)[['zz_error_contribution','x_error_contribution','observed_total_error']].mean(),['architecture','zz_error_contribution','x_error_contribution','observed_total_error'],['architecture','mean ZZ contribution','mean X contribution','mean total signed error'])
    graph=md_table(gdesc,['architecture','nodes','edges','degree_sequence','diameter','average_shortest_path_length'],['graph','nodes','edges','degree sequence','diameter','mean path length'])
    pair=paired.iloc[0]
    e4_summary_path=ROOT/'results/supplementary/tables/E4_pattern_summary.csv'
    e4_pair_path=ROOT/'results/supplementary/tables/E4_paired_differences.csv'
    if e4_summary_path.is_file() and e4_pair_path.is_file():
        e4s=pd.read_csv(e4_summary_path);e4p=pd.read_csv(e4_pair_path)
        e4_pairs=e4p[e4p.g.astype(str)=='all']
        e4_summary_table=md_table(e4s,['pattern','architecture','n_runs','optimizer_success_count','optimizer_failure_count','compiled_cx_count_mean','compiled_depth_mean','routing_swap_count_mean','noisy_absolute_error_mean','shot_sem_mean'],['pattern','architecture','runs','optimizer successes','optimizer failures','mean CX','mean depth','mean routing SWAPs','mean noisy abs error','mean shot SEM'])
        e4_pair_table=md_table(e4_pairs,['pattern','n_pairs','mean','sample_sd','sem'],['pattern','matched pairs','mean A−B','sample SD','SEM'])
        ring_a=e4s[(e4s.pattern=='ring')&(e4s.architecture=='Processor A_branch')].iloc[0]
        ring_b=e4s[(e4s.pattern=='ring')&(e4s.architecture=='Processor B_ref12')].iloc[0]
        ring_pair=e4_pairs[e4_pairs.pattern=='ring'].iloc[0]
        star_a=e4s[(e4s.pattern=='star')&(e4s.architecture=='Processor A_branch')].iloc[0]
        star_b=e4s[(e4s.pattern=='star')&(e4s.architecture=='Processor B_ref12')].iloc[0]
        e4_observation=(f"Descriptive observation: the ring mapped to mean CX {f(ring_a.compiled_cx_count_mean)} / {f(ring_b.compiled_cx_count_mean)} and mean routing SWAPs {f(ring_a.routing_swap_count_mean)} / {f(ring_b.routing_swap_count_mean)} on A/B; its pooled paired noisy A−B mean was {f(ring_pair['mean'])} J (sample SD {f(ring_pair['sample_sd'])}, SEM {f(ring_pair['sem'])}). For star, mean CX was {f(star_a.compiled_cx_count_mean)} / {f(star_b.compiled_cx_count_mean)} and mean noisy absolute error was {f(star_a.noisy_absolute_error_mean)} / {f(star_b.noisy_absolute_error_mean)} J. These are finite local-simulation summaries, not hardware or causal performance claims.")
        e4_section=f'''## Supplementary E4 ansatz-pattern study\n\nThis separate, pre-frozen study reuses the nine canonical path starts and optimizes ring/star once per field and initialization seed. Each fitted logical circuit is compiled to both fixed A/B graphs; no per-architecture re-optimization or post-outcome map change is made. E4 remains supplementary and does not replace the primary path results.\n\n{e4_summary_table}\n\nMatched-seed noisy-energy difference (A minus B) pooled over the nine field/seed pairs per pattern:\n\n{e4_pair_table}\n\n{e4_observation}\n\nThe full per-run table and raw optimizer/count records are under `results/supplementary/`; shot SEMs and between-start SD/SEM are different quantities. No hardware conclusion is implied.'''
        e4_report=f'''## Supplementary E4 ansatz-pattern study\n\nThe experiment followed the frozen `docs/EXPERIMENT_PLAN.md`: 27 pattern/field/start combinations, 18 new ring/star optimizations, and identical logical parameters mapped to both A/B graphs. The primary maps/settings were not changed. This table reports generated means over starts; it is separate from the canonical Stage 1 comparison.\n\n{e4_summary_table}\n\nPooled matched A-minus-B sampled-energy differences by pattern (nine field/seed pairs):\n\n{e4_pair_table}\n\n{e4_observation}\n\nSee `results/supplementary/tables/E4_ansatz_patterns.csv` for each run and `E4_paired_differences.csv` for field-specific pairs. Shot SEM is per run; the paired SEM is across matched initialization/field pairs.'''
    else:
        e4_section='''## Supplementary E4 ansatz-pattern study\n\nThe separate path/ring/star experiment is specified in `docs/EXPERIMENT_PLAN.md` and is NOT RUN in this release snapshot. No E4 performance result is claimed. The default pipeline does not execute it.'''
        e4_report='''## Supplementary E4 ansatz-pattern study\n\nThe experiment is pre-frozen in `docs/EXPERIMENT_PLAN.md` and is NOT RUN in this report snapshot. Its default status is not executed; no E4 outcome is claimed.'''
    readme=f'''# PS-S1: exact, variational, and noisy A/B simulation\n\n**Qiskit Fall Fest 2026 · Phase 1 · SRM University-AP**  \n**Team Chicken Leg Piece:** Swarup · Biswajit · Arhaan Sethi · Shorya Pratap Singh Chandrawat (submitting lead as recorded in project metadata).\n\nThis repository records a reproducible local simulation study of the four-site open transverse-field Ising model. All reported hardware-architecture outcomes are simulations under the declared synthetic noise model; no quantum hardware was run. This repository is publicly hosted on GitHub for project sharing; the local simulation workflow did not submit to the hackathon portal, and portal submission is not claimed unless confirmed by the team. No license is added because member approval was not established.\n\n## Main result\n\nThe exact reference values are cross-checked by dense and sparse spin Hamiltonians, a Qiskit Pauli operator, and an independent free-fermion spectrum. The nine canonical VQE starts are retained, including the unsuccessful optimizer termination. The separate restart diagnostic is clearly labeled and never overwrites that canonical failure. The table below pools all three initialization seeds within each field and graph; `shot SEM` is sampling uncertainty for a single run, whereas the pooled SD/SEM describe variation across starts.\n\n{table_pooled}\n\nMatched-seed sampled-energy difference, defined as A minus B over all fields and starts: **n={int(pair['n_pairs'])}, mean={f(pair['mean'])}, sample SD={f(pair['sample_sd'])}, SEM={f(pair['sem'])}**. These are descriptive paired statistics, not hardware-performance claims.\n\n## Hamiltonian and conventions\n\nThe October 14, 2026 Master Challenge Guide (page 5) specifies the open four-site model `H = −J Σᵢ ZᵢZᵢ₊₁ − g Σᵢ Xᵢ`, with `J=1` and `g` values `0.5, 1.0, 1.5`. The Hamiltonian and open boundary are settled by the guide and spectrum checks. The guide says “magnetization” but does not define its axis or normalization. We therefore label the project conventions explicitly (`Mz_per_site`, `Mx_per_site`, `Mz2_normalized`) and do not present one as source-defined.\n\n| g | exact E₀ | max spectrum diff | Σ⟨Xᵢ⟩ |\n|---|---:|---:|---:|\n{table_exact.splitlines()[2:] and chr(10).join(table_exact.splitlines()[2:])}\n\n## All canonical VQE starts\n\nThe table reports raw optimizer success separately from the project energy tolerance. The tolerance is a project reporting convention, not an organizer mandate.\n\n{table_starts}\n\n## Fixed reference graphs\n\nThe guide presents these as reference examples and permits valid participant-designed alternatives. We freeze the two reference graphs before E4; this is not hardware calibration. Their topology descriptors are descriptive and not performance evidence.\n\n{graph}\n\n## Reproduction\n\nTested with Python 3.13.16 and the exact pins in `requirements.txt`. From the repository root, create/activate a Python environment and install those pins. Then run the notebook using the standard `python3` kernel:\n\n```bash\npython3 -m nbconvert --to notebook --execute --output-dir .executed-output --ExecutePreprocessor.kernel_name=python3 main.ipynb\n```\n\nThe notebook calls the canonical pipeline in a fixed order: exact checks → graph descriptors → nine-start VQE and ideal compilation → separate restart diagnostic → fixed-model noisy sampling → pooled/paired metrics and error decomposition → processed-data export → figures → generated documentation. The manifest is a frozen release snapshot and is not regenerated as part of this command. To run the separate supplementary study after the Stage 1 gate, use `python3 scripts/run_e4_ansatz_patterns.py`; it is not part of the default workflow.\n\n{e4_section}\n\n## Methods and evaluation\n\nThe canonical objective is the expectation of the source-confirmed Hamiltonian under the four-qubit RY/CX circuit. Initialization vectors are generated with NumPy `default_rng(seed)` from a fixed uniform interval. The exact parameter-shift derivative feeds L-BFGS-B. The solver receives only the Hamiltonian and current parameters; the exact ground-state energy is read later for classification and reporting.\n\nEvery field uses the same three independent initialization seeds. No extra restart is silently counted as an independent seed. The failed optimization status remains visible. In the separate restart diagnostic, saved failed-run parameters are used to start a new optimization; that output is stored apart from canonical data.\n\nThe graphs are the guide's fixed reference examples. Their use is motivated by reproducibility and a direct comparison on the specified A/B pair, not by post-hoc selection for favorable outcomes. The guide permits valid alternatives, but this project does not change the primary maps after observing results.\n\n## Compilation and resource evidence\n\nThe logical circuit is compiled once for each graph with the same requested basis, optimization level, layout/routing methods, and transpiler seed. The compilation instrumentation records the actual pass trace and the output of routing-related passes.\n\n- `cx_count` and `depth` are read from the compiled circuit.\n- Routing-pass SWAPs and final-circuit SWAP gates are separate metrics.\n- Initial and final layouts are saved; idle physical wires are not treated as logical qubits.\n- The compiled state is reduced back to logical qubits and checked against the original ideal state.\n- No noisy-state fidelity is inferred from Pauli measurement counts.\n\n## Sampling, uncertainty, and interpretation\n\nZ and X observables are estimated in separate measurement bases with separate deterministic simulator seeds. For each basis, the declared shot count is used; the total shots per energy are the sum of the group shots. The combined shot SEM is computed from independent per-group sample variances in quadrature.\n\nThe per-run shot SEM quantifies finite-sample uncertainty under this simulator setup. The sample SD and SEM across initialization seeds quantify between-start variability. The pooled A/B comparison is descriptive; it does not by itself establish a causal or hardware ranking. The paired statistic matches A and B on both field value and VQE initialization seed.\n\nThe error decomposition evaluates exact and sampled Hamiltonian contributions separately: the three ZZ bonds and the four X fields. It reports signed component deviations, their sum, total noisy error, and a closure residual. Opposite-signed component errors can cancel, so the total absolute error is not the sum of component absolute errors.\n\n## Interpretation boundary\n\nThe synthetic noise assumptions are applied to simulated gates and readout only. They are not measured calibration data, and the five- and nine-node graphs do not identify actual quantum processors.\n\nThe report does not claim a statistically significant architecture winner, a hardware advantage, or generalization beyond the declared circuit, noise model, seeds, fields, and graph pair. The plotted error bars are explicitly ±1 shot SEM, not confidence intervals.\n\nThe undefined magnetization wording is retained as an ambiguity. It does not make the Hamiltonian uncertain: the source specifies the open-chain terms and independent spectra agree.\n\n## Metric definitions\n\n- `E₀` is the smallest eigenvalue of the open-chain Hamiltonian.\n- Signed ideal error is `E_VQE − E₀`; absolute ideal error is its magnitude.\n- Relative absolute error is `|E_est − E₀| / |E₀|`.\n- A noisy estimate uses the sampled ZZ and X contributions together.\n- Total noisy signed error is sampled energy minus `E₀`.\n- Per-run shot SEM is not a between-seed SEM and is not labeled a confidence interval.\n- The pooled table's SD uses the sample convention (`ddof=1`).\n- The paired difference is sampled A energy minus sampled B energy.\n- Optimizer success is the optimizer-reported status; the project tolerance is a separate flag.\n- Routing SWAP evidence is collected from the observed pass DAGs; final SWAP gates are counted separately.\n\n## Fixed experiment ledger\n\n- Problem instance: the guide's four-site open chain.\n- Coupling: `J=1`; the three fields appear in `data/raw/hamiltonian_s1.json`.\n- Ansatz: four RY layers and three entangler sweeps in the canonical run.\n- Parameter count: sixteen for the canonical configuration.\n- Canonical initialization seeds: 42, 7, and 21.\n- Optimizer: L-BFGS-B with exact parameter-shift gradients.\n- Basis: `rz`, `sx`, `x`, and `cx`.\n- Transpilation: optimization level 1; Sabre layout and routing; seed 42.\n- Noise and shot settings: frozen in both processor JSON files and the run tables.\n- Primary architecture rows are never selected based on their measured outcomes.\n\n## Suggested reading order\n\n1. Read the governing-source notes in `docs/SOURCES.md`.\n2. Check the model text in `data/raw/hamiltonian_s1.json`.\n3. Inspect the exact cross-check before interpreting VQE errors.\n4. Read all nine canonical starts, including the failure.\n5. Compare graph-resource evidence separately from sampled energy.\n6. Read the pooled table with its `row_type` and uncertainty definitions.\n7. Review the signed ZZ/X decomposition before interpreting total error.\n8. Use the manifest only as the hash snapshot for this frozen repository state.\n9. Treat E4 as supplementary and consult its frozen plan before invoking it.\n10. Review the scope limits before making any claim outside simulation.\n\n## Reproduction setup\n\nFrom a clean checkout or filesystem copy, create a virtual environment using the Python version used for the recorded run. Install the exact dependencies with `python3 -m pip install -r requirements.txt`. The registered Jupyter kernel name used by the notebook is `python3`.\n\nThe nbconvert command above writes the executed notebook copy to a temporary output directory. The pipeline writes regenerated deterministic project outputs under the project tree. Review `git status --short` if the directory is a Git checkout; differences must be investigated, not automatically discarded.\n\nThe standalone clean-room runner also executes pytest, writes verification logs outside the repository, and retains its scratch copy. It is a filesystem-copy check only. It does not prove that a remote Git clone, hosted CI, portal, or hardware job occurred.\n\nThe default notebook intentionally does not invoke the E4 runner, the historical COBYLA runner, or archived stress/noise experiments. The canonical reproduction script is the single source of the default pipeline order.\n\n## Key files\n\n- `main.ipynb`: executable analysis and visible result tables/figures.\n- `report.md`: canonical Markdown report at repository root, presenting the verified Phase 1 A/B benchmark analysis and the clearly separated proposed Processor D design ideology.\n- `src/problem.py`, `src/ansatz.py`, `src/vqe.py`: model, ansatz and optimizer. `make_ansatz` retains its historical default of two repetitions; the canonical workflow explicitly uses three.\n- `src/routing.py`, `src/metrics.py`, `src/visualization.py`: evidence-based compilation, metrics and plots.\n- `data/raw/hamiltonian_s1.json`: source-verified model inputs; not a substitute for missing source documents.\n- `results/raw/`: exact and VQE/noisy count records. `results/tables/`: generated tables; `data/processed/`: analysis-ready copies with a data dictionary.\n- `processors/`: frozen A/B reference graphs and synthetic noise settings. `results/experiment_manifest.json`: path-safe SHA-256 snapshot.\n- `docs/`: source, specification, QA, glossary, reproduction and rubric notes. `docs/EXPERIMENT_PLAN.md` freezes the supplementary E4 design.\n\n## Scope and limitations\n\nThis repository is publicly hosted on GitHub. No hardware execution, portal access, organizer contact, team/problem selection check, or hackathon portal submission is claimed; the local workflow did not submit to the hackathon portal. The separate AI policy referenced by the instructions was not supplied; contributors must confirm the applicable policy. No license is included because explicit approval from all four members was not obtained. The supplied source ZIP and `Problem_Statment_Details.pdf` were absent from the available workspace; the private handoff records this provenance limitation. No ZIP-based extraction or checksum comparison is claimed.\n'''
    report=f'''# PS-S1 simulation report\n\n## Pooled A/B comparison (first result)\n\n{table_pooled}\n\nAll measurements are local simulations under the stated synthetic channel model. The pooled means average three VQE initializations per field and architecture; the nine matched pairs are the independent comparison units for the descriptive paired statistic. Shot SEM is not a confidence interval.\n\n### Paired sampled-energy difference\n\nA minus B over the nine matched `(g, initialization seed)` pairs: **mean {f(pair['mean'])}; sample SD {f(pair['sample_sd'])}; SEM {f(pair['sem'])}; n={int(pair['n_pairs'])}**. No CI is claimed.\n\n### Sampled error decomposition\n\nThe sampled energy is the sum of its separately measured ZZ and X contributions. These are mean signed contributions to noisy-minus-exact error over the three fields and three starts per architecture; component errors can have opposite signs.\n\n{table_dec}\n\nThe decomposition closes to floating-point precision on a per-run basis (check `noisy_error_decomposition.csv`). `shot_sem_total` combines independent Pauli-group SEMs in quadrature.\n\n{e4_report}\n\n## Exact references\n\n{table_exact}\n\nThe maximum spectral discrepancies in the table are checked directly from generated spectra; the full eigenvalue spectra and exact observables are retained in the cross-check artifacts. The source-confirmed model is an open chain; the undefined magnetization axis/normalization remains explicitly disclosed.\n\n## Canonical VQE and separate restart\n\nAll nine starts, including the seed-42 `g=1.5` iteration-limit failure, are visible in the README table and `ideal_architecture_results.csv`. The restart diagnostic is stored separately and is not substituted for that canonical run. The exact reference is used only for post-optimization classification and error measurement, not as the VQE objective.\n\n## Architecture, routing and noise\n\nThe two fixed graphs are the guide's A/B references, with five and nine physical nodes. Compilation uses basis `{{rz,sx,x,cx}}`, level one, Sabre layout/routing and transpiler seed 42. The generated tables record actual pass traces, initial/final layouts, routing SWAP evidence, final-circuit SWAP count, CX count, depth, and semantic preservation. No hardware calibration is implied. The noise model uses per-gate depolarizing channels and symmetric readout flips as recorded in the processor JSON and per-run results; Z/X observables use independent simulator seeds and 4096 shots each.\n\n## Proposed Processor D Design Ideology (Proposal Only — Not a Phase 1 Benchmark)\n\nThis section presents a conceptual architecture proposal addressing the hackathon judging criterion for Phase 1. As clarified by organizers, implementation and benchmarking of Processors C and D are not Phase 1 requirements; this section documents design rationale, topological trade-offs, and future empirical verification criteria without claiming implementation or simulation outcomes.\n\n### 1. Measured and Simulated Phase 1 Evidence (Verified Repository Baseline)\n\nThe empirical baseline established in this repository rests strictly on the two fixed reference graphs under the declared synthetic noise model:\n- **Processor A (`A_branch`)**: 5 nodes, 4 undirected edges `(0,1), (1,2), (1,3), (3,4)`, degree sequence `[3, 2, 1, 1, 1]`, tree (diameter 3, no cycles).\n- **Processor B (`B_ref12`)**: 9 nodes, 12 undirected edges, degree sequence `[4, 4, 3, 3, 3, 3, 2, 2, 2]`, diameter 4, contains multiple cycles (including 3 4-cycles $C_4$).\n- **Canonical Open-Chain VQE Benchmark**: For the primary 4-site open TFIM ($H = -J \\sum_{{i=0}}^2 Z_i Z_{{i+1}} - g \\sum_{{i=0}}^3 X_i$, $J=1$, $g \\in \\{{0.5, 1.0, 1.5\\}}$), the 16-parameter `reps=3` nearest-neighbor CX ansatz compiled to exactly 9 CX, depth 23, and 0 routing SWAPs on both Processor A and Processor B across all nine canonical starts. Under the declared synthetic noise model (single-qubit $p=0.001$, CX $p=0.005$, readout $p=0.01$), the matched-seed paired energy difference $E_{{\\text{{noisy}},A}} - E_{{\\text{{noisy}},B}}$ over the 9 pairs yielded mean +0.00944 J, sample SD 0.05350 J, SEM 0.01783 J ($n=9$). The standard error of the mean exceeds the mean, demonstrating no statistically resolvable performance advantage between A and B for the open-chain problem.\n- **Supplementary E4 Ansatz-Pattern Study**: When evaluating non-linear entangling structures on these fixed graphs, routing overhead diverged:\n  - On Processor A (tree), the 12-CX logical ring ansatz required 5 routing SWAPs, resulting in mean compiled CX 27 and depth 55, with mean noisy absolute error 0.813639 J.\n  - On Processor B (mesh containing cycles), the ring ansatz mapped with 0 routing SWAPs, compiling to 12 CX and depth 28, with mean noisy absolute error 0.528862 J.\n  - The paired ring noisy difference (A minus B) was mean +0.284776 J (sample SD 0.122527 J, SEM 0.0408422 J, $n=9$). E4 remains supplementary evidence illustrating that topological mismatch induces SWAP overhead on cycle circuits.\n\n### 2. Conceptual Processor D Proposal (Design Rationale & Trade-offs)\n\n- **Proposed Topology**: A 4-qubit simple cycle graph ($C_4$), defined on physical vertices $V = \\{{0, 1, 2, 3\\}}$ with 4 bidirectional edges:\n  $$E = \\{{(0, 1), (1, 2), (2, 3), (3, 0)\\}}$$\n- **Topological Fit and Direct Interaction Mapping**:\n  - *Open Chain Mapping*: The 4-site open-chain TFIM requires interactions across three nearest-neighbor bonds: `(0,1)`, `(1,2)`, and `(2,3)`. The path subgraph $P_4 \\subset C_4$ natively executes these interactions with 0 routing SWAPs and identity layout $q_i \\mapsto i$.\n  - *Periodic / Ring Flexibility*: The additional coupler `(3,0)` natively closes the loop. Should periodic boundary conditions ($Z_3 Z_0$) or ring-entangled ansätze be deployed, the circuit compiles directly with 0 routing SWAPs and minimal depth, avoiding the 5-SWAP routing penalty observed on acyclic trees like Processor A.\n  - *Graph Diameter & Homogeneity*: $C_4$ is 2-regular (every node has degree 2) with diameter 2. Unlike Processor A (degrees 3, 2, 1) and Processor B (degrees 4, 3, 2), every physical qubit experiences identical topological connectivity, eliminating degree-heterogeneity and routing bottlenecks.\n- **Comparison Against Baselines**:\n  - *vs. Minimal Linear Path ($P_4$, 4 nodes, 3 edges)*: $P_4$ has diameter 3 and requires SWAP gates to interact qubits 0 and 3. $C_4$ adds exactly one physical coupler `(3,0)`, reducing diameter from 3 to 2 and supporting cyclic permutations without increasing node count.\n  - *vs. Processor A (`A_branch`, 5 nodes, 4 edges)*: Processor A leaves physical node 4 as a leaf and contains a high-degree hub (node 1) that cannot close loops. $C_4$ uses fewer physical qubits (4 vs 5) while providing cycle closure.\n  - *vs. Processor B (`B_ref12`, 9 nodes, 12 edges)*: Processor B achieves zero-SWAP routing for both path and ring circuits, but requires 9 physical qubits (5 idle spectator qubits during a 4-qubit benchmark). $C_4$ provides the identical zero-SWAP routing capability for $P_4$ and $C_4$ circuits with a compact, dedicated 4-qubit footprint.\n- **Physical Assumptions, Coupler Overheads & Limitations**:\n  - *Coupler Overhead*: In superconducting transmon architectures, closing a planar 4-qubit loop requires routing an additional transmission-line or capacitive coupler `(3,0)`. An extra coupler introduces additional potential pathways for parasitic stray capacitive coupling, residual $ZZ$ interaction, and idle qubit dephasing.\n  - *Crosstalk Not Measured*: While $C_4$ eliminates idle spectator qubits present in Processor B, any potential crosstalk mitigation or frequency crowding penalty is purely an unmodeled physical conjecture; the project's synthetic noise model does not incorporate spatial crosstalk or frequency collision physics.\n  - *Scale Invariance*: $C_4$ is purpose-built for 4-site systems. It does not generalize to larger problem instances ($N > 4$) without expansion to larger 2D grid/heavy-hex layouts.\n\n### 3. Future Empirical Verification (Requirements for a Phase 2 Study)\n\nTo validate this proposal empirically in a future development phase, the following evaluations would be required:\n1. **Physical or Calibrated Simulation**: Incorporate calibrated hardware backend noise (e.g., via fake backend or pulse-level Hamiltonian models) reflecting actual transmon qubit frequency assignments and residual $ZZ$ crosstalk on the $C_4$ loop.\n2. **Compilation Benchmarking**: Transpile the canonical open-chain and periodic ansätze onto the $C_4$ coupling map to verify zero-SWAP routing pass schedules and analyze gate parallelism.\n3. **Comparative Noisy Execution**: Execute identical randomized benchmarking and noisy VQE runs comparing $P_4$, $C_4$, and the full 9-node $B$ mesh under identical gate error rates to isolate the impact of idle spectators vs. extra coupler calibration overhead.\n\n## Provenance and limitations\n\nThe October 14, 2026 guide is the governing specification. The input Hamiltonian data file records the exact guide page for the model. The magnetization wording is genuinely underspecified; the Hamiltonian and boundary condition are not. The supplied source ZIP and `Problem_Statment_Details.pdf` were absent from the workspace, so ZIP extraction/hash verification is unavailable. This repository is publicly hosted on GitHub. No quantum hardware execution, portal contact, or hackathon portal submission is claimed; the local simulation workflow did not submit to the hackathon portal. The separate AI policy was not supplied, and no project license was added without all-member approval.\n'''
    (ROOT/'README.md').write_bytes(readme.encode('utf-8'))
    (ROOT/'report.md').write_bytes(report.encode('utf-8'))
    print(f"Rendered README.md ({len(readme.splitlines())} lines) and report.md from generated tables.")
if __name__=='__main__':main()
